package com.bakeflow.inventory.infrastructure.web;
import com.bakeflow.inventory.application.*;import com.bakeflow.inventory.application.InventoryDtos.*;import com.bakeflow.inventory.domain.LocationType;import java.net.URI;import java.util.*;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/locations")public class LocationController{private final InventoryCatalogService service;LocationController(InventoryCatalogService s){service=s;}
@GetMapping public PageResult<LocationView>list(@RequestParam(required=false)String search,@RequestParam(required=false)LocationType type,@RequestParam(required=false)Boolean active,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.searchLocations(search,type,active,page,size);}@GetMapping("/tree")public List<LocationView>tree(){return service.locationTree();}@GetMapping("/{id}")public LocationView get(@PathVariable UUID id){return service.getLocation(id);}@PostMapping public ResponseEntity<LocationView>create(@RequestBody LocationInput input){var l=service.createLocation(input);return ResponseEntity.created(URI.create("/api/v1/locations/"+l.id())).body(l);}@PutMapping("/{id}")public LocationView update(@PathVariable UUID id,@RequestBody LocationInput input){return service.updateLocation(id,input);}@PatchMapping("/{id}/activate")public LocationView activate(@PathVariable UUID id){return service.setLocationActive(id,true);}@PatchMapping("/{id}/deactivate")public LocationView deactivate(@PathVariable UUID id){return service.setLocationActive(id,false);}}
